 void addToCart(JSONObject p){if(p.optString("type").equals("variable")||p.optBoolean("range")){officialCheckout(p.optString("url"));return;}if(cartBusy)return;cartAction("/add-item",payload("id",p.optInt("id"),"quantity",1));}
